#pragma once

#include <string>

// Statically-compiled program identity/version info, kept separate from
// application logic so it can be updated (or generated by a build step)
// without touching other translation units.
namespace Version {
// The program's name wherever it is SHOWN or used to name its files
// (settings, log). The ONE place it is written. "QSpice" is a registered
// trademark, so it must not appear in the name.
inline constexpr const char *kProgramName = "QSchView";

// True in a Debug build. Used to mark every displayed version string.
//
// NDEBUG rather than _DEBUG: it is the standard's own switch, set by
// every Release configuration, so this does not depend on MSVC's
// spelling.
#ifdef NDEBUG
inline constexpr bool kIsDebugBuild = false;
#else
inline constexpr bool kIsDebugBuild = true;
#endif

inline constexpr int kVersionMajor = 0;
inline constexpr int kVersionMinor = 1;
inline constexpr int kVersionPatch = 0;

// "0.1.0", or "0.1.0 (DEBUG)" in a Debug build.
//
// The ONE place a version is formatted, so the debug marker cannot be
// shown in the title bar and missed in the About box.
std::string versionStr();

// "QSchView v0.1.0" -- the window title before a file name is added.
std::string winTitleStr();
} // namespace Version
